// Spáruje úkoly s účastníky, označí nejisté vlastníky a zahodí nepodložené termíny.
const vysledek = $('Shrnutí a úkoly').first().json.output ?? {};
const vstup = $('Nová porada').first().json.body ?? {};
const ucastnici = Array.isArray(vstup.ucastnici) ? vstup.ucastnici : [];

// Porovnáváme bez diakritiky a bez velkých písmen, aby se jana novakova
// spárovala s Jana Nováková.
const norm = (s) => String(s ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

function najdiUcastnika(jmeno) {
  const hledane = norm(jmeno);
  if (!hledane) {
    return { jmeno: '', email: '', jiste: false, poznamka: 'u ukolu neni uveden nikdo' };
  }

  // 1. Přesná shoda celého jména.
  const presne = ucastnici.filter((u) => norm(u.jmeno) === hledane);
  if (presne.length === 1) {
    return { jmeno: presne[0].jmeno, email: presne[0].email, jiste: true, poznamka: '' };
  }

  // 2. Shoda na jednu část jména (krestni nebo prijmeni) — jen pokud je jediná.
  const castecne = ucastnici.filter((u) => norm(u.jmeno).split(' ').includes(hledane));
  if (castecne.length === 1) {
    return { jmeno: castecne[0].jmeno, email: castecne[0].email, jiste: true, poznamka: '' };
  }
  if (castecne.length > 1) {
    return {
      jmeno: String(jmeno),
      email: '',
      jiste: false,
      poznamka: 'podobnych jmen je ' + castecne.length + ', prirazeni musi potvrdit zapisovatel'
    };
  }

  return { jmeno: String(jmeno), email: '', jiste: false, poznamka: 'jmeno neni na seznamu ucastniku' };
}

const ukoly = Array.isArray(vysledek.ukoly) ? vysledek.ukoly : [];

return ukoly.map((u, i) => {
  const osoba = najdiUcastnika(u.vlastnik);
  const poznamky = [];
  if (!osoba.jiste) poznamky.push(osoba.poznamka);

  // AI občas doplní termín, který nikdo nevyslovil. Bereme jen termíny,
  // u kterých model potvrdil, že v zápisu opravdu byly.
  const termin = u.terminZmineny === true ? String(u.termin ?? '') : '';
  if (!termin && u.termin) {
    poznamky.push('termin ' + u.termin + ' nebyl v zapisu vysloven, nebyl prevzat');
  }

  return {
    json: {
      poradaId: String(vstup.poradaId ?? $execution.id),
      poradaNazev: String(vstup.nazev ?? 'Porada'),
      poradaDatum: String(vstup.datum ?? $now.toISODate()),
      cislo: i + 1,
      zadani: String(u.zadani ?? ''),
      vlastnik: osoba.jmeno,
      email: osoba.email,
      termin,
      jisteVlastnik: osoba.jiste,
      poznamka: poznamky.filter(Boolean).join('; '),
      shrnuti: String(vysledek.shrnuti ?? '')
    }
  };
});

