// Seskupí úkoly z Notion podle vlastníka. Každý dostane jen svoje.
const stranky = $input.first().json.results ?? [];

// Z Notion vlastnosti vytáhne čistý text podle jejího typu.
const text = (prop) => {
  if (!prop) return '';
  if (prop.type === 'title') return (prop.title ?? []).map((t) => t.plain_text).join('');
  if (prop.type === 'rich_text') return (prop.rich_text ?? []).map((t) => t.plain_text).join('');
  if (prop.type === 'email') return prop.email ?? '';
  if (prop.type === 'date') return prop.date?.start ?? '';
  if (prop.type === 'select') return prop.select?.name ?? '';
  return '';
};

const podleEmailu = {};

for (const stranka of stranky) {
  const p = stranka.properties ?? {};
  const email = text(p['E-mail']);
  const stav = text(p['Stav']);

  // Úkol bez jasného vlastníka se nikomu neposílá. Zůstane v Notion
  // a zapisovatel ho uvidí ve svém mailu.
  if (!email) continue;
  if (stav === 'Odesláno') continue;

  if (!podleEmailu[email]) {
    podleEmailu[email] = {
      email,
      jmeno: text(p['Vlastník']),
      porada: text(p['Porada']),
      radky: []
    };
  }

  const termin = text(p['Termín']);
  podleEmailu[email].radky.push(
    '- ' + text(p['Úkol']) + (termin ? ' (termín ' + termin + ')' : ' (termín neurčen)')
  );
}

return Object.values(podleEmailu).map((u) => ({
  json: {
    email: u.email,
    jmeno: u.jmeno,
    porada: u.porada,
    pocet: u.radky.length,
    seznam: u.radky.join('\n')
  }
}));
